SELECT * FROM report_assignments
WHERE template_id = #{templateId}
  AND period_label IN

    #{periodLabel}

mapper.select:
SELECT * FROM report_assignments
WHERE template_id = #{templateId}
  AND period_label = #{periodLabel}
  AND assigned_to_company_id = #{companyId}
LIMIT 1

mapper.update:
UPDATE report_assignments
SET status = #{status}
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM report_submissions
WHERE assignment_id = #{assignmentId}
  AND status NOT IN ('draft', 'rejected', 'returned')

choose.when:
SELECT template_id, COUNT(*) AS cnt FROM report_assignments WHERE template_id IN
#{templateId}
GROUP BY template_id

mapper.select:
SELECT a.issuer_department_id AS groupId, COALESCE(c.name, '未指定部门') AS groupName, COUNT(*) AS total, COUNT(DISTINCT a.template_id) AS templates, COUNT(DISTINCT a.assigned_to_company_id) AS companies, SUM(a.status IN ('pending', 'filling')) AS filling, SUM(a.status = 'submitted') AS reviewing, SUM(a.status IN ('pending_receipt', 'approved')) AS pendingReceipt, SUM(a.status IN ('received', 'aggregated')) AS received, SUM(a.status IN ('rejected', 'returned')) AS rejected, SUM(a.status = 'recalled') AS recalled FROM report_assignments a LEFT JOIN companies c ON c.id = a.issuer_department_id
WHERE a.issuer_department_id = #{companyId}
WHERE a.assigned_to_company_id = #{companyId}
GROUP BY a.issuer_department_id, c.name ORDER BY total DESC
